// Some portions generated by Claude
import { layoutCommunities } from './graph-layout-topology.ts';
import { computeNetworkLayout } from './graph-layout-network.ts';
import { graphNodeSize } from './graph-geometry.ts';
import {LAYOUT_SPACING as gap} from './graph-layout-spacing.ts';
import type { LayoutOptions } from './graph-layout-engine.ts';
import type { Graph, GraphNode, PointerPosition } from './graph-types.ts';

const COARSE_LINKS_PER_CLUSTER = 6;

/**
 * The links between neighbourhoods (keyed "a:b", weighted by how many statements join them) that are among the
 * `perCluster` strongest of either end; ties go to the earlier key.
 */
export function strongestLinks(weights: ReadonlyMap<string, number>, perCluster: number) {
  const byCluster = new Map<string, Array<[string, number]>>();
  for (const entry of weights) {
    for (const end of entry[0].split(':')) {
      let list = byCluster.get(end);
      if (!list) byCluster.set(end, (list = []));
      list.push(entry);
    }
  }
  const kept = new Set<string>();
  for (const list of byCluster.values()) {
    list.sort((left, right) => right[1] - left[1] || (left[0] < right[0] ? -1 : left[0] > right[0] ? 1 : 0));
    for (let at = 0; at < Math.min(perCluster, list.length); at++) kept.add(list[at][0]);
  }
  return kept;
}

/** Community coarsening bounds the expensive solver, independent of RDF shape.
 * All real nodes/edges survive. Within large neighborhoods use topology-ordered
 * compact rows; only their quotient graph enters the rectangle-aware solver.
 */
export function computeMultilevelLayout(graph: Graph, options: LayoutOptions = {}) {
  const {topology, partition} = layoutCommunities(graph);
  const visited = new Uint8Array(graph.nodes.length), owner = new Uint32Array(graph.nodes.length);
  const clusters: number[][] = [];
  for (let seed = 0; seed < graph.nodes.length; seed++) {
    if (visited[seed]) continue;
    const queue = [seed];
    visited[seed] = 1;
    let members: number[] = [];
    for (let i = 0; i < queue.length; i++) {
      const node = queue[i];
      if (members.length === 256) {clusters.push(members); members = [];}
      owner[node] = clusters.length; members.push(node);
      topology.forEachNeighbor(String(node), id => {
        const next = Number(id);
        if (!visited[next] && partition[next] === partition[seed]) {visited[next] = 1; queue.push(next);}
      });
    }
    if (members.length) clusters.push(members);
  }
  const positions = new Map<string, PointerPosition>(), sizes = new Map<string, {width: number; height: number}>();
  const coarse: Graph = {nodes: [], edges: [], revision: graph.revision};
  clusters.forEach((members, cluster) => {
    let width = 0, height = 0;
    for (const index of members) {const node = graph.nodes[index], size = options.nodeSizes?.get(node.id) ?? graphNodeSize(node); width = Math.max(width, size.width); height = Math.max(height, size.height);}
    const sx = width + gap.nodeGapX, sy = height + gap.nodeGapY;
    const columns = Math.max(1, Math.ceil(Math.sqrt(members.length * sy / sx)));
    const rows = Math.ceil(members.length / columns);
    const size = {width: columns * sx + gap.groupGap, height: rows * sy + gap.groupGap};
    const id = String(cluster);
    sizes.set(id, size);
    coarse.nodes.push({id, label: 'Neighborhood ' + cluster, kind: 'iri'} as GraphNode);
    members.forEach((index, i) => {
      const row = Math.floor(i / columns), col = row % 2 ? columns - 1 - i % columns : i % columns;
      positions.set(graph.nodes[index].id, {x: (col - (columns - 1) / 2) * sx, y: (row - (rows - 1) / 2) * sy});
    });
  });
  const weights = new Map<string, number>();
  topology.forEachEdge((_edge, _attributes, a, b) => {
    const source = owner[Number(a)], target = owner[Number(b)];
    if (source === target) return;
    const key = source < target ? source + ':' + target : target + ':' + source;
    weights.set(key, (weights.get(key) ?? 0) + 1);
  });
  // A random 50,000-node graph links nearly every neighbourhood to every other (18,000 links between 221), which took
  // fCoSE 15 s; the strongest few per neighbourhood keep related ones together.
  for (const key of strongestLinks(weights, COARSE_LINKS_PER_CLUSTER)) {
    const [source, target] = key.split(':');
    coarse.edges.push({id: key, source, target, predicate: 'urn:layout:adjacent', label: ''});
  }
  let centers: Map<string, PointerPosition>;
  if (clusters.length <= 400) {
    centers = computeNetworkLayout(coarse, {nodeSizes: sizes}).positions;
  } else {
    // Thousands of isolated/tiny neighborhoods need packing, not a global
    // dense matrix. Preserve community locality without quadratic storage.
    centers = new Map();
    const area = [...sizes.values()].reduce((sum, size) => sum + size.width * size.height, 0);
    const targetWidth = Math.sqrt(area * (options.aspectRatio ?? 1.6));
    let x = 0, y = 0, rowHeight = 0;
    for (const node of coarse.nodes) {
      const size = sizes.get(node.id)!;
      if (x && x + size.width > targetWidth) {x = 0; y += rowHeight + gap.groupGap; rowHeight = 0;}
      centers.set(node.id, {x: x + size.width / 2, y: y + size.height / 2});
      x += size.width + gap.groupGap; rowHeight = Math.max(rowHeight, size.height);
    }
  }
  clusters.forEach((members, cluster) => {
    const center = centers.get(String(cluster))!;
    members.forEach(index => {
      const p = positions.get(graph.nodes[index].id)!;
      p.x += center.x; p.y += center.y;
    });
  });
  return {positions, bends: new Map<string, number>()};
}
